import React, { useEffect, useState } from "react";

export default function AdminUserHistory({ onCancel }) {
  const [withdrawHistory, setWithdrawHistory] = useState([]);
  const [depositHistory, setDepositHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setLoading(true);
    setMessage("");

    try {
      const [withdrawRes, depositRes] = await Promise.all([
        fetch("http://localhost:8080/api/withdraw/all", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
        fetch("http://localhost:8080/api/deposit/all-history", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }),
      ]);

      if (!withdrawRes.ok || !depositRes.ok) {
        throw new Error("Failed to load data.");
      }

      const [withdrawData, depositData] = await Promise.all([
        withdrawRes.json(),
        depositRes.json(),
      ]);

      setWithdrawHistory(withdrawData);
      setDepositHistory(depositData);
    } catch (err) {
      console.error(err);
      setMessage("Failed to load transaction history.");
    } finally {
      setLoading(false);
    }
  };

  const renderStatusBadge = (status) => {
    const colors = {
      PENDING: "bg-yellow-500",
      APPROVED: "bg-green-600",
      REJECTED: "bg-red-600",
      COMPLETED: "bg-blue-600",
    };
    return (
      <span
        className={`px-2 py-1 rounded-full text-xs font-semibold text-white ${colors[status] || "bg-gray-500"}`}
      >
        {status}
      </span>
    );
  };

  const renderTable = (title, data, type) => (
    <div className="bg-white shadow rounded-xl mb-10 overflow-hidden border">
      <div className="px-6 py-4 bg-gray-100 border-b text-gray-800 font-bold text-lg flex items-center gap-2">
        {type === "withdraw" ? "🧾 Withdraw History" : "💰 Deposit History"}
      </div>
      <div className="overflow-auto">
        <table className="min-w-[1000px] w-full text-sm text-gray-700">
          <thead className="bg-gray-50 text-xs text-gray-700 uppercase sticky top-0 z-10">
            <tr>
              <th className="px-6 py-3 text-left">ID</th>
              <th className="px-6 py-3 text-left">Email</th>
              <th className="px-6 py-3 text-left">Amount</th>
              <th className="px-6 py-3 text-left">Method</th>
              <th className="px-6 py-3 text-left">Txn ID</th>
              <th className="px-6 py-3 text-left">
                {type === "withdraw" ? "Receiver" : "Sender"} Number
              </th>
              <th className="px-6 py-3 text-left">Status</th>
              <th className="px-6 py-3 text-left">Date</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200 bg-white">
            {data.map((item, index) => (
              <tr key={item.id || index} className="hover:bg-gray-50">
                <td className="px-6 py-3">{item.id}</td>
                <td className="px-6 py-3 whitespace-nowrap">
                  {item.user?.email || item.email || "N/A"}
                </td>
                <td className="px-6 py-3 font-medium">
                  ৳ {Number(item.amount).toFixed(2)}
                </td>
                <td className="px-6 py-3">{item.method}</td>
                <td className="px-6 py-3">{item.transactionId}</td>
                <td className="px-6 py-3">
                  {type === "withdraw" ? item.receiverNumber : item.senderNumber}
                </td>
                <td className="px-6 py-3">{renderStatusBadge(item.status)}</td>
                <td className="px-6 py-3">
                  {new Date(item.requestedAt).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-4 py-10">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
          📊 All User Transaction History
        </h1>
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-sm shadow"
        >
          ← Back to Home
        </button>
      </div>

      {loading ? (
        <p className="text-center text-gray-600 text-lg">Loading...</p>
      ) : message ? (
        <p className="text-center text-red-600 font-semibold">{message}</p>
      ) : (
        <>
          {renderTable("Deposit History", depositHistory, "deposit")}
          {renderTable("Withdraw History", withdrawHistory, "withdraw")}
        </>
      )}
    </div>
  );
}
